function [x] = fast_context(jd0_utc, t, r, density_scale)
%FAST_CONTEXT  The context at t seconds after the epoch jd0_utc (a UTC Julian date), the satellite at r (J2000): the Sun and the Moon
%   at the TT date, the Sun's pressure at the satellite, the density at the geodetic height of r (ECEF by the GMST build)
%   times the activity factor.
%   jd0_utc: real[1] (passed a plain number)
%   t: real[1] (passed a plain number)
%   r: real[m][3] (passed in m)
%   density_scale: real[1] (passed a plain number)
%   returns x: FastCtx (passed rec)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    x = asils.models.orbitfast.FastCtx_zero();
    jd_tt = (jd0_utc + ((t + 69.184) / 86400));
    x = asils.models.orbitfast.FastCtx_zero();
    x.sun = asils.models.sunfast.sun_position_fast(jd_tt);
    x.moon = asils.models.moonfast.moon_position_fast(jd_tt);
    c = asils.models.caltime.eci_to_ecef((jd0_utc + (t / 86400)));
    [lat, lon, h] = asils.models.truthfield.geodetic5(asils.pc.mv(c, r));
    x.p_srp = asils.models.sunfast.solar_pressure_at(asils.pc.norm_((x.sun - r)));
    x.rho = asils.models.truthdensity.density_scaled(h, density_scale);
end
